    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    names = sorted(packages)

    # Each bound is the intersection of all constraints on an installed package.
    bounds = {}
    for name, interval in roots.items():
        bounds[name] = (interval[0], interval[1])

    best = None
    best_vector = None

    def search(assigned, required):
        nonlocal best, best_vector

        for name, version in assigned.items():
            low, high = required[name]
            if version < low or version > high:
                return

        unresolved = [name for name in required if name not in assigned]
        if not unresolved:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(assigned)
                best_vector = vector
            return

        name = min(unresolved)
        if name not in packages:
            return
        low, high = required[name]
        forbidden = blocked.get(name, [])
        choices = sorted(
            (row for row in packages[name]
             if low <= row['version'] <= high
             and row['version'] not in forbidden
             and (name not in pins or row['version'] == pins[name])),
            key=lambda row: row['version'], reverse=True
        )

        for row in choices:
            version = row['version']
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_required = dict(required)
            valid = True
            for dep in row.get('deps', []):
                dep_name = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                if dep_name in next_required:
                    old_low, old_high = next_required[dep_name]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_required[dep_name] = (dep_low, dep_high)
            if valid:
                search(next_assigned, next_required)

    search({}, bounds)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
